imageHint: "Kulikovo Field memorial column and church",
    descriptionAdvanced: {
      de: "Das weite Kulikowo-Feld im Gouvernement Tula ist ein zentraler Ort der mittelalterlichen russischen Geschichte, an dem sich 1380 das Schicksal der Region entschied. Unter der Führung von Großfürst Dmitri Donskoi traten die vereinten russischen Streitkräfte den Truppen der Goldenen Horde unter dem Befehlshaber Mamai entgegen. Dieser entscheidende Sieg am 8. September schwächte die mongolisch-tatarische Herrschaft erheblich und stärkte die Vorherrschaft Moskaus über die anderen russischen Fürstentümer. Heute ist das Gebiet ein staatliches historisches Reservat, das durch ein modernes interaktives Museumsgebäude direkt am Ort der Schlacht ergänzt wird. Das Museum präsentiert archäologische Funde wie Pfeilspitzen, Kettenhemden und antike Waffen, die auf dem Feld ausgegraben wurden. Das Zentrum der Gedenkstätte bildet das Rote-Hügel-Denkmal mit seiner hoch aufragenden Gusseisensäule. Die weitläufige Steppenlandschaft, die sorgfältig in ihren ursprünglichen Zustand zurückversetzt wird, vermittelt den Besuchern ein authentisches Gefühl für die Dimensionen dieses legendären militärischen Aufeinandertreffens.",
      hu: "A Tula megyében található kiterjedt Kulikovói mező a középkori orosz történelem központi jelentőségű helyszíne, ahol 1380-ban eldőlt a régió sorsa. Dmitrij Donszkoj nagyfejedelem vezetésével az egyesült orosz haderők itt szálltak szembe az Arany Horda csapataival, amelyeket Mamaj hadvezér irányított. Szeptember 8-i döntő győzelmük jelentősen meggyengítette a mongol-tatár uralmat, és megerősítette Moszkva vezető szerepét a többi orosz fejedelemség felett. Ma a terület állami történelmi rezervátum, amelyet a csata pontos helyszínén felépített modern, interaktív múzeumépület egészít ki. A kiállítás az ásatások során előkerült nyílhegyeket, láncingeket és korabeli fegyvereket mutat be. Az emlékhely központja a Vörös-domb, ahol a magasba nyúló öntöttvas emlékoszlop áll. A gondosan eredeti állapotába visszaállított sztyeppei táj hiteles képet nyújt a látogatóknak erről a legendás katonai összecsapásról és annak hatalmas földrajzi dimenzióiról.",
      ro: "Vasta Câmpie Kulikovo din regiunea Tula este un loc central al istoriei medievale ruse, unde soarta regiunii a fost decisă în 1380. Sub conducerea Marelui Prinț Dmitri Donskoi, forțele ruse unite au înfruntat trupele Hoardei de Aur conduse de comandantul Mamai. Această victorie decisivă din 8 septembrie a slăbit semnificativ dominația mongolo-tătară și a consolidat supremația Moscovei asupra celorlalte principate rusești. Astăzi, zona este o rezervație istorică de stat, completată de o clădire muzeală modernă și interactivă chiar pe locul bătăliei. Muzeul prezintă descoperiri arheologice, cum ar fi vârfuri de săgeți, cămăși de zale și arme antice excavate de pe câmp. Centrul memorialului este reprezentat de monumentul Dealul Roșu, cu coloana sa înaltă din fontă. Peisajul extins de stepă, restaurat cu grijă la starea sa inițială, oferă vizitatorilor o perspectivă autentică asupra dimensiunilor acestei confruntări militare legendare din Evul Mediu.",
      en: "The vast Kulikovo Field in the Tula region is a central site of medieval Russian history, where the fate of the region was decided in 1380. Under the leadership of Grand Prince Dmitri Donskoi, the united Russian forces confronted the troops of the Golden Horde commanded by Mamai. This decisive victory on September 8 significantly weakened Mongol-Tatar rule and solidified Moscow's supremacy over other Russian principalities. Today, the area is a state historical reserve, complemented by a modern interactive museum building located directly on the battlefield. The museum showcases archaeological finds such as arrowheads, chainmail, and ancient weapons excavated from the field. The focal point of the memorial is the Red Hill monument, featuring its towering cast-iron column. The expansive steppe landscape, carefully restored to its original ecological state, provides visitors with an authentic sense of the vast scale of this legendary medieval military clash.",
      es: "El vasto Campo de Kulikovo, en la gobernación de Tula, es un lugar central de la historia medieval rusa donde se decidió el destino de la región en 1380. Bajo el mando del Gran Príncipe Dmitri Donskói, las fuerzas rusas unidas se enfrentaron a las tropas de la Horda de Oro dirigidas por el comandante Mamái. Esta victoria crucial del 8 de septiembre debilitó significativamente el dominio mongol-tártaro y fortaleció la supremacía de Moscú sobre otros principados rusos. Hoy en día, la zona es una reserva histórica estatal, complementada por un moderno edificio de museo interactivo situado directamente en el lugar de la batalla. El museo presenta hallazgos arqueológicos como puntas de flecha, cotas de malla y armas antiguas excavadas en el campo. El centro del monumento es el monumento de la Colina Roja, con su imponente columna de hierro fundido. El extenso paisaje de estepa, cuidadosamente restaurado a su estado original, ofrece a los visitantes una sensación auténtica de las dimensiones de este legendario enfrentamiento militar.",
      pt: "O vasto Campo de Kulikovo, na província de Tula, é um local central da história medieval russa, onde o destino da região foi decidido em 1380. Sob a liderança do Grão-Duque Dmitri Donskoy, as forças russas unidas enfrentaram as tropas da Horda de Ouro comandadas pelo líder Mamai. Esta vitória decisiva em 8 de setembro enfraqueceu significativamente o domínio mongol-tártaro e fortaleceu a supremacia de Moscovo sobre os outros principados russos. Hoje, a área é uma reserva histórica estatal, complementada por um moderno edifício de museu interativo localizado diretamente no sítio da batalha. O museu apresenta achados arqueológicos como pontas de seta, cotas de malha e armas antigas escavadas no campo. O centro do memorial é o monumento da Colina Vermelha, com a sua imponente coluna de ferro fundido. A extensa paisagem de estepe, cuidadosamente restaurada ao seu estado original, proporciona aos visitantes uma sensação autêntica das dimensões deste lendário confronto militar.",
      fr: "Le vaste Champ de Koulikovo, dans le gouvernement de Toula, est un lieu central de l'histoire médiévale russe, où le sort de la région s'est joué en 1380. Sous la direction du grand-prince Dimitri Donskoï, les forces russes unies ont affronté les troupes de la Horde d'Or commandées par le chef Mamaï. Cette victoire décisive du 8 septembre a considérablement affaibli la domination mongolo-tatare et a renforcé la suprématie de Moscou sur les autres principautés russes. Aujourd'hui, la zone est une réserve historique d'État, complétée par un bâtiment de musée interactif moderne situé directement sur le lieu de la bataille. Le musée présente des découvertes archéologiques telles que des pointes de flèches, des cottes de mailles et des armes anciennes exhumées sur le terrain. Le centre du mémorial est constitué par le monument de la Colline Rouge, avec son imposante colonne en fonte. Le vaste paysage de steppe, soigneusement restauré dans son état d'origine, donne aux visiteurs un sentiment authentique des dimensions de cet affrontement militaire légendaire.",
    },
