imageHint: "The Motherland Calls statue Mamayev Kurgan Volgograd",
    descriptionAdvanced: {
      de: "Der Mamajew-Hügel erhebt sich über Wolgograd als ein monumentales Zeugnis des sowjetischen Widerstands während der Schlacht von Stalingrad im Zweiten Weltkrieg. Zwischen September 1942 und Januar 1943 fanden an den Hängen dieser strategischen Anhöhe erbitterte Nahkämpfe statt, wobei die Kontrolle über den Hügel mehrfach zwischen deutschen und sowjetischen Truppen wechselte. Nach dem Krieg wurde hier ein gewaltiger Gedenkkomplex errichtet, dessen Herzstück die gigantische Statue \"Mutter Heimat ruft\" bildet, die mit ihrem erhobenen Schwert über die Stadt wacht. Der Aufstieg zur Spitze führt über 200 Granitstufen, die symbolisch für die 200 Tage der Stalingrader Schlacht stehen. Entlang des Weges passieren die Besucher emotionale Skulpturengruppen, riesige Steinmauern mit heroischen Reliefs und die Halle des militärischen Ruhms, in der eine ewige Flamme von Soldaten der Ehrengarde bewacht wird. Dieser Ort ist nicht nur ein Architekturdenkmal, sondern auch ein riesiges Massengrab.",
      hu: "A Mamajev-kurgan Volgográd fölé magasodva állít monumentális emléket a szovjet ellenállásnak a második világháborús sztálingrádi csata idején. 1942 szeptembere és 1943 januára között ádáz közelharcok zajlottak ennek a stratégiai dombnak a lejtőin, és a magaslat irányítása többször is gazdát cserélt a német és a szovjet csapatok között. A háború után egy hatalmas emlékkomplexumot építettek ide, amelynek központja a felemelt karddal a város felett őrködő gigantikus \"A Haza hív\" szobor. A csúcsra vezető út pontosan 200 gránitlépcsőből áll, amely szimbolikusan a sztálingrádi csata 200 napját jelképezi. Az út mentén a látogatók drámai szoborcsoportokat, hősies domborművekkel díszített hatalmas kőfalakat és a Katonai Dicsőség Csarnokát érintik, ahol az öröklángot díszőrség őrzi. Ez a hely nemcsak építészeti emlékmű, hanem egy hatalmas tömegsír is, amely a tragédia méreteit hirdeti.",
      ro: "Mamaev Kurgan se înalță deasupra orașului Volgograd ca un monument impresionant al rezistenței sovietice în timpul Bătăliei de la Stalingrad din al Doilea Război Mondial. Între septembrie 1942 și ianuarie 1943, pe pantele acestei coline strategice au avut loc lupte corp la corp crâncene, controlul asupra dealului trecând de mai multe ori de la germani la sovietici. După război, aici a fost construit un complex memorial masiv, a cărui piesă centrală este gigantica statuie \"Patria Mamă te cheamă\", care veghează asupra orașului cu sabia ridicată. Urcușul spre vârf constă în 200 de trepte de granit, reprezentând simbolic cele 200 de zile ale bătăliei de la Stalingrad. Pe drum, vizitatorii trec pe lângă grupuri sculpturale emoționante, ziduri imense de piatră cu reliefuri eroice și Sala Gloriei Militare, unde o flacără eternă este păzită de soldații gărzii de onoare. Acest loc este și o imensă groapă comună.",
      en: "Mamayev Kurgan rises above Volgograd as a monumental testament to Soviet resistance during the Battle of Stalingrad in World War II. Between September 1942 and January 1943, fierce hand-to-hand combat took place on the slopes of this strategic hill, with control passing multiple times between German and Soviet forces. After the war, a massive memorial complex was constructed here, centered around the gigantic \"The Motherland Calls\" statue, which watches over the city with its raised sword. The ascent to the summit consists of exactly 200 granite steps, symbolically representing the 200 days of the Stalingrad battle. Along the way, visitors pass emotional sculptural groups, huge stone walls featuring heroic reliefs, and the Hall of Military Glory, where an eternal flame is guarded by an honor guard. This site serves not only as an architectural masterpiece but also as an immense mass grave commemorating the massive loss of life.",
      es: "El Mamáyev Kurgán se alza sobre Volgogrado como un testimonio monumental de la resistencia soviética durante la Batalla de Stalingrado en la Segunda Guerra Mundial. Entre septiembre de 1942 y enero de 1943, en las laderas de esta altura estratégica se produjeron encarnizados combates cuerpo a cuerpo, cambiando el control de la colina varias veces entre las tropas alemanas y soviéticas. Tras la guerra, se erigió aquí un enorme complejo conmemorativo, cuya pieza central es la gigantesca estatua \"La Madre Patria llama\", que vigila la ciudad con su espada en alto. El ascenso a la cima consta de 200 escalones de granito, que simbolizan los 200 días de la Batalla de Stalingrado. A lo largo del camino, los visitantes pasan por emotivos grupos escultóricos, enormes muros de piedra con relieves heroicos y la Sala de la Gloria Militar, donde una llama eterna es custodiada por soldados de la guardia de honor. Este lugar no es solo un monumento arquitectónico, sino también una fosa común de dimensiones inmensas.",
      pt: "O Mamayev Kurgan ergue-se sobre Volgogrado como um testemunho monumental da resistência soviética durante a Batalha de Estalinegrado na Segunda Guerra Mundial. Entre setembro de 1942 e janeiro de 1943, ocorreram combates corpo a corpo ferozes nas encostas desta colina estratégica, com o controlo da colina a alternar várias vezes entre as tropas alemãs e soviéticas. Após a guerra, foi construído aqui um enorme complexo memorial, cujo elemento central é a gigantesca estátua \"A Mãe Pátria\", que vigia a cidade com a sua espada erguida. A subida ao topo é feita por 200 degraus de granito, simbolizando os 200 dias da Batalha de Estalinegrado. Ao longo do caminho, os visitantes passam por grupos escultóricos emotivos, enormes paredes de pedra com relevos heróicos e o Salão da Glória Militar, onde uma chama eterna é guardada por soldados da guarda de honra. Este local não é apenas um monumento arquitetónico, mas também uma vala comum gigante.",
      fr: "Le Kourgane Mamaïev s'élève au-dessus de Volgograd comme un témoignage monumental de la résistance soviétique pendant la bataille de Stalingrad lors de la Seconde Guerre mondiale. Entre septembre 1942 et janvier 1943, des combats acharnés au corps à corps se sont déroulés sur les pentes de cette hauteur stratégique, le contrôle de la colline changeant plusieurs fois de mains entre les troupes allemandes et soviétiques. Après la guerre, un immense complexe commémoratif a été érigé ici, dont la pièce maîtresse est la statue gigantesque \"L'Appel de la Mère-Patrie\", qui veille sur la ville avec son épée levée. La montée vers le sommet se fait par 200 marches de granit, symbolisant les 200 jours de la bataille de Stalingrad. Le long du chemin, les visiteurs passent devant des groupes de sculptures émouvants, d'énormes murs de pierre aux reliefs héroïques et la salle de la Gloire militaire, où une flamme éternelle est gardée par des soldats de la garde d'honneur. Ce lieu n'est pas seulement un monument architectural, mais aussi une immense fosse commune.",
    },
