      hu: ["Történelmi negyed Moszkvában", "Számos építészeti emlék", "A nemesség egykori lakónegyede", "Központi elhelyezkedés Moszkvában"],
      ro: ["Cartier istoric în Moscova", "Numeroase monumente de arhitectură", "Fost cartier rezidențial al nobilimii", "Situat central în Moscova"],
      en: ["Historic neighborhood in Moscow", "Numerous architectural monuments", "Former residential quarter of the nobility", "Centrally located in Moscow"],
      es: ["Barrio histórico en Moscú", "Numerosos monumentos arquitectónicos", "Antiguo barrio residencial de la nobleza", "Ubicación central en Moscú"],
      pt: ["Bairro histórico em Moscovo", "Inúmeros monumentos arquitetónicos", "Antigo bairro residencial da nobreza", "Localização central em Moscovo"],
