      pt: ["Fundado em 1912", "Arquiteto Semyon Kallistratov", "Famoso centro de educação musical", "Joia arquitetónica neogótica"],
      fr: ["Fondé en 1912", "Architecte Semion Kallistratov", "Centre d'éducation musicale célèbre", "Joyau de l'architecture néogothique"],
