      pt: ["O museu foi fundado em 1775.", "A coleção inclui 7.200 itens.", "O rifle mais antigo data de 1590.", "A área de exposição é de 1.200 metros quadrados.", "O museu abriga um cañón do século XVII.", "Anualmente, 200.000 pessoas visitam o museu."],
