      ro: ["Finalizat în 1956", "Arhitectură: stalinism", "Centru cultural în Ural", "Scenă mare pentru balet"],
      en: ["Completion 1956", "Architecture: Stalinism", "Cultural center in the Urals", "Major stage for ballet"],
      es: ["Finalización en 1956", "Arquitectura: Estalinismo", "Centro cultural en los Urales", "Gran escenario para ballet"],
      pt: ["Conclusão em 1956", "Arquitetura: Stalinismo", "Centro cultural nos Urais", "Grande palco para balé"],
      fr: ["Achèvement en 1956", "Architecture : Stalinienne", "Centre culturel dans l'Oural", "Grande scène de ballet"],
