      en: ["Built between 1723 and 1726.", "Naryshkin Baroque architectural style.", "The iconostasis is 25 meters high.", "Commemorates Peter the Great's visit.", "Returned to the church in 1989.", "Located on the highest point of central Kazan."],
      es: ["La catedral fue consagrada en 1726.", "El campanario mide 52 metros de altura.", "La longitud total es de 40 metros.", "El iconostasio mide 10 metros de altura.", "La catedral fue dañada por un incendio en 1815.", "La restauración se llevó a cabo en 1825."],
      pt: ["A catedral foi consagrada em 1726.", "A torre sineira tem 52 metros de altura.", "O comprimento total é de 40 metros.", "A iconostase tem 10 metros de altura.", "A catedral foi danificada por um incêndio em 1815.", "A restauração ocorreu em 1825."],
