      en: ["Total height of 97 meters.", "Built between 1998 and 2009.", "Capacity of 5,000 worshippers.", "Neo-Byzantine architectural style.", "Enshrines the relics of St. Mitrophan.", "Third largest cathedral in Russia."],
      es: ["La catedral tiene 97 metros de altura.", "Los costes de construcción fueron de 1.000 millones de rublos.", "La superficie total es de 4.000 metros cuadrados.", "La catedral fue consagrada en 2009.", "Las cúpulas tienen un diámetro de 12 metros.", "El carillón incluye 12 campanas."],
