      fr: ["La cathédrale mesure 97 mètres de haut.", "Les coûts de construction s'élèvent à 1 milliard de roubles.", "La surface au sol est de 4 000 mètres carrés.", "La cathédrale a été consacrée en 2009.", "Les dômes ont un diamètre de 12 mètres.", "Le carillon comprend 12 cloches."],
