      en: ["Built between 1677 and 1772.", "Iconostasis is 30 meters high.", "Home of the Smolensk Mother of God icon.", "Baroque style with 5 domes.", "Survived 1812 and WWII unscathed.", "Main spiritual center of Smolensk."],
