      fr: ["Érigée entre 1101 et 1102 sous le prince Vladimir Monomaque.", "Hauteur de la coupole : 35 mètres.", "Iconostase du XVIIIe siècle.", "Reconstruction après destruction entre 1677 et 1740.", "Longueur de 50 mètres, largeur de 30 mètres.", "Possède 5 coupoles."],
