      en: "A historical fortress in Vologda that once served as a defensive post for the Russian north.",
      es: "Una fortificación histórica en Vologda que en el pasado sirvió como puesto de defensa clave para el norte de Rusia.",
      pt: "Uma fortificação histórica em Vologda que outrora serviu como posto de defesa para o norte da Rússia.",
      fr: "Une fortification historique à Vologda qui servait autrefois de poste de défense pour le Nord de la Russie.",
